\end{align}
Define the centralizer of $g$ in $S_{n}$:
\begin{align}
Z_{g} \ceq \{ c \in S_{n} \mid cg = gc \}.
\end{align}
Then $\vt{Z_{g}}$ depends only on the cycle type $\la$, and
\begin{align}
\vt{Z_{g}} = 1^{m_{1}}m_{1}!\, 2^{m_{2}}m_{2}! \cdots n^{m_{n}}m_{n}!.
\end{align}

